package httpapi

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"strings"

	"github.com/danielgtaylor/huma/v2"

	"github.com/entirehq/entire-api/internal/brainbuild"
)

// The OPEN PROPOSAL SET surface: the review queue in front of a branch's durable
// fact-set head, served as ONE compare-and-swapped blob rather than a row per
// proposal.
//
// The shape is dictated by ADR-P1-E: the merge runs on the runner. The runner reads
// the fact head and the open set, computes the resolution locally, and swaps BOTH
// back under the refs it read. This server never interprets a proposal — it stores
// bytes and moves pointers. A row model would force the server to re-derive which
// entries survive a resolution, which is merge logic, and a second implementation of
// merge logic is exactly the divergence the wire contract exists to prevent. It would
// also fork proposal identity: ids are derived by the client from the proposal's own
// fields, and a server-side id derived from storage coordinates could never match.
//
// Paths sit under the fact-set family (/brain/facts/proposals) because the set IS the
// fact set's review queue, and the client addresses it there.

// brainProposal is one entry in the set. The server treats Proposal as opaque JSON:
// only the client derives or interprets it, so a newer client may add fields without
// a server change.
type brainProposal struct {
	ID       string          `json:"id"`
	Proposal json.RawMessage `json:"proposal"`
}

// BrainProposalsListInput is GET /repos/{repo_id}/brain/facts/proposals?branch=
type BrainProposalsListInput struct {
	RepoID string `path:"repo_id"`
	Branch string `query:"branch"`
}

// BrainProposalsListOutput is the branch's open set at the ref it was read at. Found
// is false — with an empty list, not an error — when the branch has no set yet: a
// branch with no cross-member conflict simply has nothing to review.
type BrainProposalsListOutput struct {
	Body struct {
		Found     bool            `json:"found"`
		Ref       string          `json:"ref"`
		Version   int64           `json:"version"`
		Proposals []brainProposal `json:"proposals"`
	}
}

// BrainProposalGetInput is GET /repos/{repo_id}/brain/facts/proposals/{proposal_id}
type BrainProposalGetInput struct {
	RepoID     string `path:"repo_id"`
	ProposalID string `path:"proposal_id"`
	Branch     string `query:"branch"`
}

// BrainProposalGetOutput carries the entry when present. found=false is a normal
// answer (settled by someone else meanwhile), not a 404, so a client reconciling its
// local queue can tell "gone" from "the request failed".
type BrainProposalGetOutput struct {
	Body struct {
		Found    bool           `json:"found"`
		Ref      string         `json:"ref"`
		Proposal *brainProposal `json:"proposal"`
	}
}

// BrainProposalsPublishInput is POST /repos/{repo_id}/brain/facts/proposals — replace
// the whole set under CAS. OldRef is the ref the caller read; empty means "no set
// yet" (a create).
type BrainProposalsPublishInput struct {
	RepoID string `path:"repo_id"`
	Body   struct {
		Branch    string          `json:"branch"`
		OldRef    string          `json:"oldRef"`
		Proposals []brainProposal `json:"proposals"`
	}
}

// BrainProposalsPublishOutput reports the new head. Changed is false when the set was
// byte-identical to the current one, in which case Ref/Version echo the head that
// already existed — a no-op, not a failure, so a republish is idempotent.
type BrainProposalsPublishOutput struct {
	Body struct {
		Ref     string `json:"ref"`
		Version int64  `json:"version"`
		Changed bool   `json:"changed"`
	}
}

// BrainProposalResolveInput is POST .../proposals/{proposal_id}/resolve: the runner's
// computed settlement, compare-and-swapping BOTH heads from the refs it read.
type BrainProposalResolveInput struct {
	RepoID     string `path:"repo_id"`
	ProposalID string `path:"proposal_id"`
	Body       struct {
		Branch      string `json:"branch"`
		Decision    string `json:"decision"`
		FactsOldRef string `json:"factsOldRef"`
		Data        []byte `json:"data"`
		// FactsUnchanged settles WITHOUT touching the fact head. It is how an orphaned
		// proposal — one whose facts are gone entirely — is pruned: it cannot be
		// accepted, and reject changes no facts, so the only write it needs is the set.
		// Valid only with decision=reject; Data is then empty and must NOT be read as
		// "empty the fact set".
		FactsUnchanged  bool            `json:"factsUnchanged"`
		ProposalsOldRef string          `json:"proposalsOldRef"`
		Proposals       []brainProposal `json:"proposals"`
	}
}

// BrainProposalResolveOutput reports where both heads landed.
type BrainProposalResolveOutput struct {
	Body struct {
		FactsRef     string `json:"factsRef"`
		ProposalsRef string `json:"proposalsRef"`
		Changed      bool   `json:"changed"`
	}
}

// decodeProposalSet reads a stored set blob. An empty blob is an empty set.
func decodeProposalSet(plaintext []byte) ([]brainProposal, error) {
	if len(plaintext) == 0 {
		return nil, nil
	}
	var out []brainProposal
	if err := json.Unmarshal(plaintext, &out); err != nil {
		return nil, err
	}
	return out, nil
}

// encodeProposalSet renders a set for storage. An explicit empty array is stored
// rather than null so the last resolution CLEARS the set with content a head can
// point at (a head always points at content).
func encodeProposalSet(in []brainProposal) ([]byte, error) {
	if in == nil {
		in = []brainProposal{}
	}
	return json.Marshal(in)
}

// listBrainProposals returns the branch's open set (repo pull).
func listBrainProposals(ctx context.Context, deps *RepoActivityDeps, in *BrainProposalsListInput) (*BrainProposalsListOutput, error) {
	if deps.Proposals == nil {
		return nil, huma.Error503ServiceUnavailable("brain proposal queue not configured")
	}
	branch := strings.TrimSpace(in.Branch)
	if branch == "" {
		return nil, huma.Error400BadRequest("branch is required")
	}
	ref, version, plaintext, found, err := deps.Proposals.Current(ctx, in.RepoID, branch)
	if err != nil {
		return nil, brainProposalStoreError(err)
	}
	out := &BrainProposalsListOutput{}
	out.Body.Found = found
	out.Body.Ref = ref
	out.Body.Version = version
	out.Body.Proposals = []brainProposal{}
	if found {
		set, decErr := decodeProposalSet(plaintext)
		if decErr != nil {
			return nil, huma.Error500InternalServerError("stored proposal set is unreadable")
		}
		if set != nil {
			out.Body.Proposals = set
		}
	}
	return out, nil
}

// getBrainProposal returns one entry by id. Absent is found=false, not 404 — see
// BrainProposalGetOutput.
func getBrainProposal(ctx context.Context, deps *RepoActivityDeps, in *BrainProposalGetInput) (*BrainProposalGetOutput, error) {
	if deps.Proposals == nil {
		return nil, huma.Error503ServiceUnavailable("brain proposal queue not configured")
	}
	branch := strings.TrimSpace(in.Branch)
	if branch == "" {
		return nil, huma.Error400BadRequest("branch is required")
	}
	id := strings.TrimSpace(in.ProposalID)
	if id == "" {
		return nil, huma.Error400BadRequest("proposal_id is required")
	}
	ref, _, plaintext, found, err := deps.Proposals.Current(ctx, in.RepoID, branch)
	if err != nil {
		return nil, brainProposalStoreError(err)
	}
	out := &BrainProposalGetOutput{}
	out.Body.Ref = ref
	if !found {
		return out, nil
	}
	set, decErr := decodeProposalSet(plaintext)
	if decErr != nil {
		return nil, huma.Error500InternalServerError("stored proposal set is unreadable")
	}
	for i := range set {
		if set[i].ID == id {
			out.Body.Found = true
			out.Body.Proposal = &set[i]
			break
		}
	}
	return out, nil
}

// publishBrainProposals replaces the whole set under CAS (repo push).
func publishBrainProposals(ctx context.Context, deps *RepoActivityDeps, in *BrainProposalsPublishInput) (*BrainProposalsPublishOutput, error) {
	if deps.Proposals == nil {
		return nil, huma.Error503ServiceUnavailable("brain proposal queue not configured")
	}
	branch := strings.TrimSpace(in.Body.Branch)
	if branch == "" {
		return nil, huma.Error400BadRequest("branch is required")
	}
	plaintext, err := encodeProposalSet(in.Body.Proposals)
	if err != nil {
		return nil, huma.Error400BadRequest("proposals could not be encoded")
	}
	newRef, version, err := deps.Proposals.Advance(ctx, in.RepoID, branch, in.Body.OldRef, plaintext)
	out := &BrainProposalsPublishOutput{}
	switch {
	case err == nil:
		out.Body.Ref = newRef
		out.Body.Version = version
		out.Body.Changed = true
		return out, nil
	case errors.Is(err, brainbuild.ErrNoFactSetChange):
		// Byte-identical to the current set: idempotent republish. Echo the head.
		ref, v, _, _, curErr := deps.Proposals.Current(ctx, in.RepoID, branch)
		if curErr != nil {
			return nil, brainProposalStoreError(curErr)
		}
		out.Body.Ref = ref
		out.Body.Version = v
		out.Body.Changed = false
		return out, nil
	default:
		return nil, brainProposalStoreError(err)
	}
}

// resolveBrainProposal applies the runner's settlement: swap the fact head (unless
// the settlement touches no facts) and the proposal set, each from the ref the runner
// read. Either CAS losing is a 412 — the runner re-reads and re-resolves.
func resolveBrainProposal(ctx context.Context, deps *RepoActivityDeps, in *BrainProposalResolveInput) (*BrainProposalResolveOutput, error) {
	if deps.Proposals == nil || deps.Facts == nil {
		return nil, huma.Error503ServiceUnavailable("brain proposal queue not configured")
	}
	branch := strings.TrimSpace(in.Body.Branch)
	if branch == "" {
		return nil, huma.Error400BadRequest("branch is required")
	}
	if strings.TrimSpace(in.ProposalID) == "" {
		return nil, huma.Error400BadRequest("proposal_id is required")
	}
	decision := strings.TrimSpace(in.Body.Decision)
	if decision != "accept" && decision != "reject" {
		return nil, huma.Error400BadRequest("decision must be accept or reject")
	}
	if in.Body.FactsUnchanged && decision != "reject" {
		// Guard the prune path at the boundary: skipping the fact write on an accept
		// would retire the proposal while silently dropping its merge result.
		return nil, huma.Error400BadRequest("factsUnchanged is only valid with decision=reject")
	}
	if !in.Body.FactsUnchanged && len(in.Body.Data) == 0 {
		return nil, huma.Error400BadRequest("data is required (a fact-set head always points at content)")
	}

	// FACTS FIRST. A settlement that advances facts but loses the proposal-set CAS
	// leaves a settled fact set with the entry still queued — the runner re-reads and
	// re-resolves, and re-applying the same settlement is a no-op. The reverse order
	// could drop the entry while the facts never moved, losing the settlement.
	factsRef := in.Body.FactsOldRef
	if !in.Body.FactsUnchanged {
		newFactsRef, _, err := deps.Facts.Advance(ctx, in.RepoID, branch, in.Body.FactsOldRef, in.Body.Data)
		switch {
		case err == nil:
			factsRef = newFactsRef
		case errors.Is(err, brainbuild.ErrNoFactSetChange):
			// The resolution produced the current content: keep the head as-is.
		default:
			return nil, brainProposalStoreError(err)
		}
	}

	remaining, err := encodeProposalSet(in.Body.Proposals)
	if err != nil {
		return nil, huma.Error400BadRequest("proposals could not be encoded")
	}
	out := &BrainProposalResolveOutput{}
	out.Body.FactsRef = factsRef
	newSetRef, _, err := deps.Proposals.Advance(ctx, in.RepoID, branch, in.Body.ProposalsOldRef, remaining)
	switch {
	case err == nil:
		out.Body.ProposalsRef = newSetRef
		out.Body.Changed = true
		return out, nil
	case errors.Is(err, brainbuild.ErrNoFactSetChange):
		ref, _, _, _, curErr := deps.Proposals.Current(ctx, in.RepoID, branch)
		if curErr != nil {
			return nil, brainProposalStoreError(curErr)
		}
		out.Body.ProposalsRef = ref
		out.Body.Changed = false
		return out, nil
	default:
		return nil, brainProposalStoreError(err)
	}
}

// brainProposalStoreError maps store faults to the status codes the runner's retry
// loop is written against: a lost CAS is 412 (re-read and re-resolve), an
// unresolvable repo is 404 (fail closed), anything else is 500.
func brainProposalStoreError(err error) error {
	switch {
	case errors.Is(err, brainbuild.ErrFactRefConflict):
		return huma.Error412PreconditionFailed("proposal set advanced concurrently; re-read and re-resolve")
	case errors.Is(err, brainbuild.ErrRepoNotFound):
		return huma.NewError(http.StatusNotFound, "repo not found")
	default:
		return huma.Error500InternalServerError("brain proposal store unavailable")
	}
}

