package httpapi

import (
	"context"
	"encoding/json"
	"net/http"
	"testing"

	"github.com/danielgtaylor/huma/v2"

	"github.com/entirehq/entire-api/internal/brainbuild"
	"github.com/entirehq/entire-api/internal/brainstore"
	"github.com/entirehq/entire-api/internal/snapshotcrypt/snapshotcrypttest"
)

// newProposalsTest wires Mem-backed fact-set AND proposal-set heads behind
// RepoActivityDeps. They share the encrypting store (as production does) but hold
// SEPARATE ref indexes, which is the point: the two heads must move independently.
func newProposalsTest() *RepoActivityDeps {
	inner := brainstore.NewMemStore()
	enc := brainstore.NewEncryptingStore(inner, snapshotcrypttest.NewCipher(), brainstore.NewMemDEKStore())
	resolver := fakeSlugResolver{slug: factsSlug}
	facts := brainbuild.NewFactSetStore(enc, brainbuild.NewMemFactRefIndex(), resolver)
	proposals := brainbuild.NewProposalSetStore(enc, brainbuild.NewMemFactRefIndex(), resolver)
	return &RepoActivityDeps{Facts: facts, Proposals: proposals}
}

// proposalEntry builds one set entry with the client's shape: a derived id plus an
// opaque proposal body the server never interprets.
func proposalEntry(t *testing.T, id, action, candidate, target string) brainProposal {
	t.Helper()
	body, err := json.Marshal(map[string]any{
		"action":       action,
		"candidate_id": candidate,
		"target_id":    target,
		"branch":       factsBranch,
		"proposed_by":  "member-A",
	})
	if err != nil {
		t.Fatal(err)
	}
	return brainProposal{ID: id, Proposal: body}
}

func publishInput(branch, oldRef string, set []brainProposal) *BrainProposalsPublishInput {
	in := &BrainProposalsPublishInput{RepoID: factsRepoID}
	in.Body.Branch = branch
	in.Body.OldRef = oldRef
	in.Body.Proposals = set
	return in
}

func resolveInput(branch, id, decision, factsOldRef string, data []byte, setOldRef string, remaining []brainProposal) *BrainProposalResolveInput {
	in := &BrainProposalResolveInput{RepoID: factsRepoID, ProposalID: id}
	in.Body.Branch = branch
	in.Body.Decision = decision
	in.Body.FactsOldRef = factsOldRef
	in.Body.Data = data
	in.Body.ProposalsOldRef = setOldRef
	in.Body.Proposals = remaining
	return in
}

func statusOf(t *testing.T, err error) int {
	t.Helper()
	var se huma.StatusError
	if !asStatusError(err, &se) {
		t.Fatalf("expected a huma.StatusError, got %v", err)
	}
	return se.GetStatus()
}

func asStatusError(err error, out *huma.StatusError) bool {
	se, ok := err.(huma.StatusError)
	if ok {
		*out = se
	}
	return ok
}

// TestProposalsPublishThenList: an empty branch lists found=false with an empty set;
// after a publish the set round-trips through the CAS'd blob unchanged, including the
// opaque proposal body.
func TestProposalsPublishThenList(t *testing.T) {
	deps := newProposalsTest()
	ctx := context.Background()

	empty, err := listBrainProposals(ctx, deps, &BrainProposalsListInput{RepoID: factsRepoID, Branch: factsBranch})
	if err != nil {
		t.Fatalf("list empty: %v", err)
	}
	if empty.Body.Found {
		t.Fatal("a branch with no set must read found=false")
	}
	if empty.Body.Proposals == nil || len(empty.Body.Proposals) != 0 {
		t.Fatalf("empty set must be an empty array, not null: %+v", empty.Body.Proposals)
	}

	set := []brainProposal{proposalEntry(t, "prop-aaaa", "supersede", "fact:a", "fact:b")}
	pub, err := publishBrainProposals(ctx, deps, publishInput(factsBranch, "", set))
	if err != nil {
		t.Fatalf("publish: %v", err)
	}
	if !pub.Body.Changed || pub.Body.Ref == "" {
		t.Fatalf("publish should have created a head: %+v", pub.Body)
	}

	got, err := listBrainProposals(ctx, deps, &BrainProposalsListInput{RepoID: factsRepoID, Branch: factsBranch})
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	if !got.Body.Found || len(got.Body.Proposals) != 1 {
		t.Fatalf("published set did not round-trip: %+v", got.Body)
	}
	if got.Body.Proposals[0].ID != "prop-aaaa" {
		t.Fatalf("client-derived id was not preserved: %q", got.Body.Proposals[0].ID)
	}
	// The server must not reinterpret the proposal body.
	var decoded map[string]any
	if err := json.Unmarshal(got.Body.Proposals[0].Proposal, &decoded); err != nil {
		t.Fatalf("proposal body is not intact JSON: %v", err)
	}
	if decoded["candidate_id"] != "fact:a" || decoded["proposed_by"] != "member-A" {
		t.Fatalf("proposal body was altered: %+v", decoded)
	}
}

// TestProposalsPublishStaleOldRefConflicts: a publish from a ref another member has
// already moved past must lose the CAS with 412, never clobber.
func TestProposalsPublishStaleOldRefConflicts(t *testing.T) {
	deps := newProposalsTest()
	ctx := context.Background()

	first, err := publishBrainProposals(ctx, deps, publishInput(factsBranch, "",
		[]brainProposal{proposalEntry(t, "prop-aaaa", "supersede", "fact:a", "fact:b")}))
	if err != nil {
