// TestProposalResolveAdvancesBothHeads is the settlement path: the runner sends the
// resolved fact set and the remaining proposals, each under the ref it read, and both
// heads move together.
func TestProposalResolveAdvancesBothHeads(t *testing.T) {
	deps := newProposalsTest()
	ctx := context.Background()

	// A fact head to settle against.
	factsAdv, err := advanceBrainFacts(ctx, deps, advanceInput(factsBranch, "", []byte(`{"id":"fact:a"}`)))
	if err != nil {
		t.Fatalf("seed facts: %v", err)
	}
	set := []brainProposal{
		proposalEntry(t, "prop-aaaa", "supersede", "fact:a", "fact:b"),
		proposalEntry(t, "prop-bbbb", "merge", "fact:c", "fact:d"),
	}
	pub, err := publishBrainProposals(ctx, deps, publishInput(factsBranch, "", set))
	if err != nil {
		t.Fatalf("publish: %v", err)
	}

	res, err := resolveBrainProposal(ctx, deps, resolveInput(
		factsBranch, "prop-aaaa", "accept",
		factsAdv.Body.NewRef, []byte(`{"id":"fact:a","resolved":true}`),
		pub.Body.Ref, set[1:],
	))
	if err != nil {
		t.Fatalf("resolve: %v", err)
	}
	if res.Body.FactsRef == factsAdv.Body.NewRef {
		t.Fatal("accept did not advance the fact head")
	}
	if res.Body.ProposalsRef == pub.Body.Ref {
		t.Fatal("resolve did not advance the proposal set")
	}

	after, err := listBrainProposals(ctx, deps, &BrainProposalsListInput{RepoID: factsRepoID, Branch: factsBranch})
	if err != nil {
		t.Fatal(err)
	}
	if len(after.Body.Proposals) != 1 || after.Body.Proposals[0].ID != "prop-bbbb" {
		t.Fatalf("settled entry was not removed from the set: %+v", after.Body.Proposals)
	}
}

// TestProposalResolveFactsUnchangedPrunesWithoutTouchingFacts covers the orphan path:
// a proposal whose facts are gone cannot be accepted, and reject changes no facts, so
// the settlement must move ONLY the proposal set and leave the fact head exactly where
// it was.
func TestProposalResolveFactsUnchangedPrunesWithoutTouchingFacts(t *testing.T) {
	deps := newProposalsTest()
	ctx := context.Background()

	factsAdv, err := advanceBrainFacts(ctx, deps, advanceInput(factsBranch, "", []byte(`{"id":"fact:a"}`)))
	if err != nil {
		t.Fatalf("seed facts: %v", err)
	}
	set := []brainProposal{proposalEntry(t, "prop-orphan", "supersede", "fact:gone", "fact:alsogone")}
	pub, err := publishBrainProposals(ctx, deps, publishInput(factsBranch, "", set))
	if err != nil {
		t.Fatalf("publish: %v", err)
	}

	in := resolveInput(factsBranch, "prop-orphan", "reject", factsAdv.Body.NewRef, nil, pub.Body.Ref, nil)
	in.Body.FactsUnchanged = true
	res, err := resolveBrainProposal(ctx, deps, in)
	if err != nil {
		t.Fatalf("prune: %v", err)
	}
	if res.Body.FactsRef != factsAdv.Body.NewRef {
		t.Fatalf("prune moved the fact head: %q -> %q", factsAdv.Body.NewRef, res.Body.FactsRef)
	}

	cur, err := currentBrainFacts(ctx, deps, currentInput(factsBranch))
	if err != nil {
		t.Fatal(err)
	}
	if cur.Body.Ref != factsAdv.Body.NewRef {
		t.Fatalf("fact head changed behind a facts-unchanged prune: %q", cur.Body.Ref)
	}
	after, err := listBrainProposals(ctx, deps, &BrainProposalsListInput{RepoID: factsRepoID, Branch: factsBranch})
	if err != nil {
		t.Fatal(err)
	}
	if len(after.Body.Proposals) != 0 {
		t.Fatalf("orphan was not pruned: %+v", after.Body.Proposals)
	}
}

