// The LIVE cross-repo round trip: the real entire-brain binary driving this service's
// real router over real HTTP.
//
// This is the check PR #64 deferred and nobody had run. Everything on both sides was
// proven against fakes, and both sides' unit suites were green while the two disagreed
// on THREE things at once — paths, settle verb, and proposal-id derivation — because
// no test crossed the boundary. A contract test pins the JSON shapes; only this proves
// the client's URLs, auth headers, status handling and CAS loop actually work against
// the handlers as registered.
//
// It runs only when ENTIRE_BRAIN_BIN points at a built brain binary, so the normal
// suite is unaffected:
//
//	cd <entire-brain> && go build -o /tmp/entire-brain ./cmd/entire-brain
//	ENTIRE_BRAIN_BIN=/tmp/entire-brain go test ./internal/httpapi/ -run TestBrainRoundTrip -v
func TestBrainRoundTripAgainstRealClient(t *testing.T) {
	bin := strings.TrimSpace(os.Getenv("ENTIRE_BRAIN_BIN"))
	if bin == "" {
		t.Skip("set ENTIRE_BRAIN_BIN to a built entire-brain binary to run the live round trip")
	}
	if _, err := os.Stat(bin); err != nil {
		t.Fatalf("ENTIRE_BRAIN_BIN=%s: %v", bin, err)
	}

	// A real router with a push-capable caller: the brain client both reads and
	// advances, so a pull-only gate would fail for the wrong reason.
	authn, mint := jwksAuth(t)
	base := baseDeps{
		Authenticator: authn,
		Reader:        fakeReaderRW([]string{factsRepoID}, []string{factsRepoID}, nil, false),
	}
	deps := newProposalsTest()
	deps.baseDeps = base
	r := NewActivityAPIRouter(deps, &UserActivityDeps{baseDeps: base, Store: fakeUserReader{}})

	srv := httptest.NewServer(r.HTTPHandler())
	t.Cleanup(srv.Close)
	token := mint(routeULID("acc1"))

	// A git repo for the brain to attach to, plus isolated config/cache so the run
	// cannot touch the developer's real brain.
	repoDir := t.TempDir()
	home := t.TempDir()
	runGit := func(args ...string) {
		t.Helper()
		cmd := exec.Command("git", args...)
		cmd.Dir = repoDir
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git %s: %v\n%s", strings.Join(args, " "), err, out)
		}
	}
	runGit("init", "-q", "-b", "main")
	runGit("config", "user.email", "member-a@example.com")
	runGit("config", "user.name", "Member A")
	if err := os.WriteFile(filepath.Join(repoDir, "README.md"), []byte("# roundtrip\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	runGit("add", "-A")
	runGit("commit", "-q", "-m", "seed")

	brain := func(t *testing.T, args ...string) (string, error) {
		t.Helper()
		ctx, cancel := contextWithTimeout(t, 90*time.Second)
		defer cancel()
		cmd := exec.CommandContext(ctx, bin, args...)
		cmd.Dir = repoDir
		cmd.Env = append(os.Environ(),
			"HOME="+home,
			"XDG_CONFIG_HOME="+filepath.Join(home, ".config"),
			"XDG_CACHE_HOME="+filepath.Join(home, ".cache"),
			"ENTIRE_BRAIN_ALLOW_HOSTED=1",
			"ENTIRE_BRAIN_NO_EGRESS=",
			"ENTIRE_BRAIN_LOCAL_ONLY=",
			"ENTIRE_API_URL="+srv.URL,
			"ENTIRE_API_TOKEN="+token,
			"ENTIRE_REPO_ID="+factsRepoID,
		)
		out, err := cmd.CombinedOutput()
		return string(out), err
	}

	// 1. SYNC against the hosted backend. This is the whole client path: resolve the
	//    backend, GET the fact head, keep-both merge, CAS it back, then read and
	//    reconcile the proposal queue.
	out, err := brain(t, "facts", "sync", "--facts-backend", "http", "--member", "member-A", "--json")
	if err != nil {
		t.Fatalf("facts sync against the live server failed: %v\n%s", err, out)
	}
	var synced map[string]any
	if jsonErr := json.Unmarshal([]byte(lastJSONLine(out)), &synced); jsonErr != nil {
		t.Fatalf("sync did not emit JSON: %v\n%s", jsonErr, out)
	}
	if synced["backend"] != "http" {
		t.Fatalf("sync did not use the hosted backend: %v", synced["backend"])
	}
	// The queue must have been REACHED, not reported unsupported: an unsupported
	// queue is exactly what a path or status mismatch looks like from the client.
	if msg, ok := synced["proposals_share_error"]; ok {
		t.Fatalf("client could not reach the hosted proposal queue: %v\n%s", msg, out)
	}

	// 2. The proposal surface must answer over the wire, with no error and no
	//    "unsupported" degrade.
	out, err = brain(t, "facts", "proposals", "list", "--branch", "main", "--json")
	if err != nil {
		t.Fatalf("facts proposals list against the live server failed: %v\n%s", err, out)
	}
	if strings.Contains(out, "unsupported") || strings.Contains(out, "no shared review queue") {
		t.Fatalf("client read the live queue as absent — path or status mismatch:\n%s", out)
	}

	// 3. And the server agrees about what it stored: the head the client advanced is
	//    readable through this service's own handler.
	cur, err := currentBrainFacts(t.Context(), deps, currentInput("main"))
	if err != nil {
		t.Fatalf("server-side read of the head the client advanced: %v", err)
	}
	if !cur.Body.Found || cur.Body.Ref == "" {
		t.Fatalf("client sync did not leave a fact head on the server: %+v", cur.Body)
	}
}

